const input = $json.body || $json;
const userMsg = (input.user_message || input.message || '').trim();
const asstReply = (input.assistant_reply || input.reply || '').trim();
const convId = input.conversation_id || null;

if (!userMsg) {
    return [{ json: { should_skip: true } }];
}

const reflectionPrompt = `You are an expert memory reflection engine for Swapnil's personal AI operating system.
Your task is to analyze the conversation turn below and extract any new permanent personal facts, preferences, technical decisions, habits, constraints, or life updates about Swapnil.

DO NOT extract:
- Casual chit-chat, greetings ("hello", "how are you", "who are you")
- Routine questions or queries asking for information ("what is X?", "tell me about Y")
- Assistant statements or speculation

DO extract:
- Personal preferences ("I prefer dark mode", "I like working late at night", "I love minimalist design")
- Technical decisions or project updates ("I decided to use FFmpeg for OpusGenAI", "I am adding Stripe to Edu51Portal")
- Life & study updates ("I finished my semester exams", "I'm travelling to Sylhet next week")
- Expressed feelings or personal relationships

Conversation Turn:
Swapnil: "${userMsg}"
Mikasa: "${asstReply}"

Output ONLY a raw JSON object with no markdown formatting and no code blocks, formatted like this:
{
  "should_store": true or false,
  "content": "Clear, standalone factual statement about Swapnil in 3rd person (e.g. 'Swapnil decided to use FFmpeg for OpusGenAI video processing.')",
  "memory_type": "fact" or "preference" or "decision" or "project" or "general",
  "importance": number from 1 to 5
}
`;

return [{
    json: {
        should_skip: false,
        user_message: userMsg,
        conversation_id: convId,
        reflection_prompt: reflectionPrompt
    }
}];

const rawText = ($json.text || '').trim();
const original = $('Prepare Reflection Prompt').first().json;

if (original.should_skip) {
    return [{ json: { should_store: false, reason: "Skipped empty input" } }];
}

let parsed = null;
try {
    // Clean code block ticks if any
    const cleanJson = rawText.replace(/^[\s\S]*?\{/, '{').replace(/\}[^\}]*$/, '}');
    parsed = JSON.parse(cleanJson);
} catch (e) {
    console.error("JSON parse error on reflection:", e.message, rawText);
    return [{ json: { should_store: false, reason: "Invalid JSON from LLM" } }];
}

if (!parsed.should_store || !parsed.content || !parsed.content.trim()) {
    return [{ json: { should_store: false, reason: "Not memory worthy" } }];
}

// Validate conversation_id as UUID or null
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const validConvId = (original.conversation_id && uuidRegex.test(original.conversation_id)) ? original.conversation_id : null;

return [{
    json: {
        should_store: true,
        content: parsed.content.trim(),
        memory_type: parsed.memory_type || "general",
        importance: parsed.importance || 3,
        conversation_id: validConvId
    }
}];

